-- T-009-03: activity_reports 120건 시드 (30 circles × 4 reports)
-- UUID 패턴: 30000000-0000-4000-8000-{circle_seq:6d}{report_idx:6d}

ON CONFLICT (id) DO UPDATE SET
  title         = EXCLUDED.title,
  content       = EXCLUDED.content,
  body          = EXCLUDED.body,
  image_url     = EXCLUDED.image_url,
  activity_type = EXCLUDED.activity_type,
  created_at    = EXCLUDED.created_at;

-- ========== activity_report_images: 리포트당 3장 ==========
-- UUID: 활동 리포트 ID 에서 마지막 4자리를 img 인덱스로 치환
-- 30000000-0000-4000-8000-000001000001 → 이미지 UUID는 img_id 테이블 사용
SELECT
  gen_random_uuid(),
  ar.id,
  'https://picsum.photos/seed/ar-' || ar.id || '-img-' || n || '/1200/800',
  n - 1
FROM public.activity_reports ar
CROSS JOIN generate_series(1, 3) AS n
WHERE ar.id::text LIKE '30000000%';
